  Time sink=Clock::now();put("core_ms",millis(started,sink));put("delivery_ms",paced?millis(origin+std::chrono::nanoseconds(int64_t(k)*50000000LL),sink):millis(started,sink));put("measure_ms",k*50.);put("release_ms",k*50.);put("enqueue_ms",millis(origin,enqueue));put("ready_ms",millis(origin,ready));put("start_ms",millis(origin,started));put("sink_ms",millis(origin,sink));
